<?php
declare(strict_types=1);
require_once __DIR__ . '/../../app/bootstrap.php'; require_once __DIR__ . '/../../app/operational_writes.php'; require_operation_post('ENTREGAS_REGISTRAR');
try{$assignment=operation_id($_POST['viaje_solicitud_id']??null);$state=strtoupper((string)($_POST['estado']??''));if(!in_array($state,['ENTREGADA','FALLIDA'],true)){throw new InvalidArgumentException('Selecciona un resultado válido.');}$receiver=$identifier=$phone=$proof=$reason=null;if($state==='ENTREGADA'){$receiver=operation_text($_POST['receptor_nombre']??null,150);$identifier=operation_text($_POST['receptor_identificacion']??null,30,false);$phone=operation_text($_POST['receptor_telefono']??null,30,false);$proof=operation_reference_url($_POST['comprobante_url']??null);}else{$reason=operation_text($_POST['motivo_fallo']??null,500);}}catch(InvalidArgumentException $exception){operation_error($exception->getMessage());}
try{$stmt=db()->prepare('EXEC dbo.sp_registrar_entrega @viaje_solicitud_id=?,@estado=?,@receptor_nombre=?,@receptor_identificacion=?,@receptor_telefono=?,@comprobante_url=?,@motivo_fallo=?;');$stmt->execute([$assignment,$state,$receiver,$identifier,$phone,$proof,$reason]);$stmt->closeCursor();}catch(PDOException $exception){operation_sql_error($exception,[50320=>'El resultado de entrega no es válido.',50321=>'La entrega exitosa exige receptor y comprobante.',50322=>'La entrega fallida exige un motivo.',50323=>'La solicitud no está en un viaje en curso.',50324=>'La solicitud ya tiene una entrega registrada.']);}operation_success('Entrega registrada correctamente.','entregaRegistrada','/entregas.php?seccion=entregas');
